style.css:
@-moz-document domain("spacehey.com") {
/* Background */
body {
    background-color: #febfdc !important; /* Updated color */
    color: #000;
}

/* Main Content */
#page {
    background-color: #ff3b96 !important; /* Updated color */
    border: 3px solid #febfdc; /* Updated color */
    border-radius: 10px;
    padding: 10px;
}

/* Sidebar */
#left, #right {
    background-color: #ffb6c1 !important;
    border: 2px solid #ff3b96; /* Updated color */
    border-radius: 10px;
    padding: 10px;
}

/* Links */
a {
    color: #ff3b96 !important; /* Updated color */
    font-weight: bold;
    text-decoration: none;
}
a:hover {
    color: #febfdc !important; /* Updated color */
    text-decoration: underline;
}

/* Headers */
h1, h2, h3 {
    color: #ff3b96 !important; /* Updated color */
    text-shadow: 1px 1px 2px #febfdc; /* Updated color */
}

/* Boxes and Tables */
.box, .table {
    background-color: #ffccdd !important; /* Updated color */
    border: 2px solid #febfdc; /* Updated color */
    padding: 10px;
    border-radius: 10px;
}

/* Buttons */
button, input[type='submit'] {
    background-color: #ff3b96 !important; /* Updated color */
    color: #fff !important;
    border: 2px solid #ff3b96; /* Updated color */
    padding: 5px 10px;
    border-radius: 5px;
    cursor: pointer;
}
button:hover, input[type='submit']:hover {
    background-color: #febfdc !important; /* Updated color */
}

/* Navbar */
.nav {
    background-color: #ff80bf !important;
    border-bottom: 3px solid #ff3b96; /* Updated color */
    padding: 5px;
}

/* Friend Boxes */
.friend {
    background-color: #ffb3c6 !important;
    border: 2px solid #ff3b96; /* Updated color */
    border-radius: 10px;
    padding: 10px;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}
::-webkit-scrollbar-track {
    background: #ff3b96; /* Updated color */
}
::-webkit-scrollbar-thumb {
    background: #ff3366;
}

/* Text Update: Cool new Divas */
.cool-new-divas {
    font-size: 24px;
    color: #ff3b96;
    text-align: center;
    margin-top: 20px;
}
}
